// Event log pane: /band-log and the band's Log button toggle it; it draws band's own lines merged with base's, slim's
// and the team plugins' straight from their state (a plugin not loaded adds nothing), and never writes any of them.
import { atom, read } from 'claude-code'
import type { EngineInterface, On } from 'claude-code'
import type { BandEvent, ForeignEvent, LogLine } from '../../types'
import { LOG_COMMAND, LOG_PANE, PREFIX_COLS, TEXT_LOG_ROWS, hhmm, kindCell, logDir, logRow, merged, newestFitting, pluginCell } from './events.ts'

const events = atom({ plugin: 'band', key: 'events' } as const, [] as BandEvent[])
const baseEvents = atom({ plugin: 'base', key: 'events' } as const, [] as ForeignEvent[])
const slimEvents = atom({ plugin: 'slim', key: 'events' } as const, [] as ForeignEvent[])
const feEvents = atom({ plugin: 'fe', key: 'events' } as const, [] as ForeignEvent[])
const qaEvents = atom({ plugin: 'qa', key: 'events' } as const, [] as ForeignEvent[])
const beEvents = atom({ plugin: 'be', key: 'events' } as const, [] as ForeignEvent[])
const pmEvents = atom({ plugin: 'pm', key: 'events' } as const, [] as ForeignEvent[])

type $ = EngineInterface

/** Only the terminal and the Desktop app draw a mod's panes; elsewhere the log goes out as text. */
async function drawsPanes($: $): Promise<boolean> {
  return (await $.session.surfaces()).some(s => s === 'terminal' || s === 'desktop')
}

async function allEvents($: $): Promise<LogLine[]> {
  return merged(await read($, events), await read($, baseEvents), await read($, slimEvents), {
    fe: await read($, feEvents),
    qa: await read($, qaEvents),
    be: await read($, beEvents),
    pm: await read($, pmEvents),
  })
}

/** The newest lines as text; an older remainder is counted and pointed at the session's files on disk. */
async function logText($: $): Promise<string> {
  const list = await allEvents($)
  if (list.length === 0) return 'no events yet'
  const shown = list.slice(-TEXT_LOG_ROWS)
  if (shown.length === list.length) return shown.map(logRow).join('\n')
  let dir: string | null = null
  try {
    dir = logDir(await $.env.get('HOME'), await $.env.get('DOMAINE_LOG_DIR'), String(await $.session.id()))
  } catch {}
  const cut = `… ${list.length - shown.length} earlier${dir === null ? '' : ` — full log: ${dir}/`}`
  return [cut, ...shown.map(logRow)].join('\n')
}

async function togglePane($: $): Promise<string> {
  if (!(await drawsPanes($))) return await logText($)
  if ((await $.ui.panes()).some(p => p.id === LOG_PANE && p.isShown)) {
    await $.ui.close({ id: LOG_PANE })
    return 'Log pane closed.'
  }
  const r = await $.ui.open({ id: LOG_PANE, title: 'Log', focus: true, closeOnEscape: true })
  if (!r.isPlaced) {
    $.ui.toast(`log pane not placed: ${r.reason}`)
    return `Log pane not placed: ${r.reason}`
  }
  return 'Log pane opened.'
}

export function registerLog(on: On): void {
  on('command.run', { command: LOG_COMMAND.name }, async $ => ({ text: await togglePane($) }))

  // Answers without next, so the band Button's own closure never runs and the pane toggles once.
  on('ui.press', { plugin: 'band', element: 'log' }, async ($, e) => {
    await togglePane($)
    return { element: e.element }
  })

  on('ui.render', { component: 'Pane', requestId: LOG_PANE }, async ($, e) => {
    const { Box, Text } = $.ui.resolve(e)
    const list = await allEvents($)
    if (list.length === 0) {
      return (
        <Box flexDirection="column" width={e.props.bodyColumns}>
          <Text dimColor wrap="truncate-end">
            no events yet
          </Text>
        </Box>
      )
    }
    // The engine's window starts at the top and never follows the end: keep the newest rows in view,
    // counting the rows a wrapped text takes.
    const rows = e.props.scroll?.bodyRows ?? 0
    const textCols = Math.max(1, e.props.bodyColumns - PREFIX_COLS)
    const shown = newestFitting(list, rows, textCols)
    const cut = shown.length < list.length
    return (
      <Box flexDirection="column" width={e.props.bodyColumns}>
        {cut ? <Text dimColor wrap="truncate-end">{`… ${list.length - shown.length} earlier`}</Text> : null}
        {shown.map((ev, i) => (
          <Box key={`ev-${i}`} flexDirection="row">
            <Box width={PREFIX_COLS} flexShrink={0}>
              <Text dimColor>{`${hhmm(ev.atMs)}  `}</Text>
              <Text dimColor>{`${pluginCell(ev.plugin)}  `}</Text>
              <Text dimColor>{`${kindCell(ev.kind)}  `}</Text>
            </Box>
            <Box width={textCols}>
              <Text wrap="wrap">{ev.text}</Text>
            </Box>
          </Box>
        ))}
      </Box>
    )
  })
}

